// Deep rooms: the inside of the graphs, and pages the house generates.
//   33 graph     · Figure 33 opens; the reader goes into it and climbs the curve to what it is fastened to
//   36 wheel     · the unscheduled year, generated by a Llull wheel cut from the reader's own rooms
//   64 registry  · the Registry files the reader: everything the house has kept, with case numbers
// Hooks (house.js, rooms in DEEP): decorate(article, ctx) · update(ctx) · leave().
//
// Everything generated here is seeded by the reader's state (walk log, fragments,
// house seq), so the same state always produces the same page. Per-room memory
// lives in localStorage `ai2053.house.deep`, stamped with ctx.escapes; it resets
// only when that changes (that is, when the house itself was left).
import { ROOMS, DIST } from "./rooms.js";
import { hash, rng, prose, redactHTML } from "./voice.js";

const root = document.documentElement;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (a, b, x) => {
  const t = clamp((x - a) / (b - a));
  return t * t * (3 - 2 * t);
};
const frag = (html) => {
  const t = document.createElement("template");
  t.innerHTML = html.trim();
  return t.content;
};
const after = (node, html) => {
  const f = frag(html);
  const first = f.firstElementChild;
  node.after(f);
  return first;
};
const pick = (r, list) => list[Math.floor(r() * list.length)];
const shuffle = (r, list) => {
  const a = [...list];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(r() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1).trimEnd() + "…" : s);
const bare = (s) => String(s).replace(/[.!?]+$/, "");
const fill = (tpl, v) => tpl.replace(/\{(\w+)\}/g, (_, k) => (v[k] ?? ""));
// {redact} is a leaking redaction: the bar, and the reader's own words leaking through it.
const fillHTML = (tpl, v) => esc(tpl).replace(/\{(\w+)\}/g, (_, k) => (k === "redact" ? redactHTML(esc(v.redact)) : esc(v[k] ?? "")));
const titleOf = (n) => ROOMS[n]?.title || `Room ${n}`;

/* ---------- memory (localStorage, stamped with the house's escapes) ---------- */

const MEM_KEY = "ai2053.house.deep";
function loadMem(ctx) {
  let m = null;
  try { m = JSON.parse(localStorage.getItem(MEM_KEY)); } catch { m = null; }
  if (!m || m.escapes !== ctx.escapes) m = { escapes: ctx.escapes, climbs: [], filings: [], wheels: [] };
  m.climbs ||= [];
  m.filings ||= [];
  m.wheels ||= [];
  return m;
}
function saveMem(m) {
  try { localStorage.setItem(MEM_KEY, JSON.stringify(m)); } catch { /* the rooms forget */ }
}
// Record that something happened at house seq `seq` (once; capped). Earlier
// records drive the page, so re-rendering the same seq gives the same page.
function mark(m, key, entry) {
  if (!m[key].some((x) => x.seq === entry.seq)) m[key].push(entry);
  if (m[key].length > 40) m[key] = m[key].slice(-40);
  saveMem(m);
}
const before = (list, seq) => list.filter((x) => x.seq < seq);

/* ---------- the reader's walk, as facts ---------- */

const MEANS = { start: "Admitted", door: "Plan", back: "Retreat", forward: "Return", jump: "No plan" };

function facts(ctx) {
  const log = ctx.walk.log;
  const plans = log.filter((s) => s.via === "door" && s.say);
  const rooms = log.map((s) => s.room);
  const recent = [];
  for (let i = rooms.length - 1; i >= 0; i--) if (!recent.includes(rooms[i])) recent.push(rooms[i]);
  const frags = [...(ctx.chaos.frags || [])].sort((a, b) => (b.last ?? 0) - (a.last ?? 0) || (b.at ?? 0) - (a.at ?? 0));
  const voids = ctx.damage.voids || 0;
  return { log, plans, rooms, recent, frags, voids, says: plans.map((s) => s.say) };
}

/* ---------- module plumbing ---------- */

let cur = null;

export function decorate(article, ctx) {
  const G = GRAMMARS[ctx.room];
  if (!G) return;
  root.dataset.grammar = G.name;
  article.dataset.grammar = G.name;
  cur = G.make(article, ctx) || {};
  cur.update?.(ctx);
}

export function update(ctx) {
  cur?.update?.(ctx);
}

export function leave() {
  cur?.leave?.();
  cur = null;
  root.classList.remove("dp-inside");
  delete root.dataset.grammar;
}

/* ======================================================================= */
/* 33 · The Steep One: Figure 33, from outside and then from inside        */
/* ======================================================================= */

// World units: x is time (12 per year from Jan 2041), y is the index, z is
// depth. The figure is the plane z = 0; the corridor opens toward -z.
const XK = 76.8; // the asymptote, 2047.4
const AK = 120;
const V0 = AK / XK;
const vAt = (x) => (x >= XK - 0.02 ? 6000 : AK / (XK - x) - V0);
const xAt = (h) => XK - AK / (h + V0);
const MARK = 66; // Reliable Agent
const H_TOP = 1000;
const CORR = 24;
const STAIR = 12;
const EYE = 5;
const NEAR = 0.6;
const PAPER = "#fffff8";
const INK = "#111";
const RED = "#b4121b";
const MONO = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
const SERIF = '"ET Book", Palatino, Georgia, serif';
const RISES = [60, 120, 240, 480, 960];

const CURVE = (() => {
  const pts = [];
  for (let x = 0; vAt(x) < 10; x += 1) pts.push([x, vAt(x)]);
  for (let h = 10; h < H_TOP + 45; h *= 1.05) pts.push([xAt(h), h]);
  return pts;
})();

const STEPS = (() => {
  const s = [];
  let x = 0;
  for (;;) {
    const h = Math.max(0, vAt(x));
    s.push([x, h]);
    if (h > H_TOP + 60) break;
    x = h < 8 ? x + 4 : xAt(h * 1.2 + 1.5);
  }
  return s;
})();

const DOTS = (() => {
  const d = [];
  for (let x = 1; x < 96; x += 2) {
    for (let y = 1; y < 60; y += 2) {
      const above = y - vAt(x);
      const r = x > XK ? 0.1 : 0.12 + 0.72 * smooth(-3, 26, above) * smooth(-24, 70, x);
      d.push([x, y, r]);
    }
  }
  return d;
})();

/* --- camera --- */

function camera(pos, yaw, pitch, F, ox, oy, W, H) {
  const cy = Math.cos(yaw), sy = Math.sin(yaw), cp = Math.cos(pitch), sp = Math.sin(pitch);
  const f = [sy * cp, sp, cy * cp];
  const r = [cy, 0, -sy];
  const u = [f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0]];
  return { p: pos, f, r, u, F, ox, oy, W, H };
}
function toCam(c, P) {
  const dx = P[0] - c.p[0], dy = P[1] - c.p[1], dz = P[2] - c.p[2];
  return [dx * c.r[0] + dy * c.r[1] + dz * c.r[2], dx * c.u[0] + dy * c.u[1] + dz * c.u[2], dx * c.f[0] + dy * c.f[1] + dz * c.f[2]];
}
const proj = (c, q) => [c.ox + (c.F * q[0]) / q[2], c.oy - (c.F * q[1]) / q[2]];
const cut = (a, b) => {
  const t = (NEAR - a[2]) / (b[2] - a[2]);
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, NEAR];
};
function seg(g, c, A, B) {
  let a = toCam(c, A), b = toCam(c, B);
  if (a[2] < NEAR && b[2] < NEAR) return;
  if (a[2] < NEAR) a = cut(a, b);
  else if (b[2] < NEAR) b = cut(b, a);
  const p = proj(c, a), q = proj(c, b);
  g.moveTo(p[0], p[1]);
  g.lineTo(q[0], q[1]);
}
function polyPath(g, c, pts) {
  const q = pts.map((P) => toCam(c, P));
  const out = [];
  for (let i = 0; i < q.length; i++) {
    const a = q[i], b = q[(i + 1) % q.length];
    const ain = a[2] >= NEAR, bin = b[2] >= NEAR;
    if (ain) out.push(a);
    if (ain !== bin) out.push(cut(a, b));
  }
  if (out.length < 3) return false;
  g.beginPath();
  out.forEach((v, i) => {
    const s = proj(c, v);
    if (i) g.lineTo(s[0], s[1]);
    else g.moveTo(s[0], s[1]);
  });
  g.closePath();
  return true;
}
function word(g, c, P, s, size, opt = {}) {
  const q = toCam(c, P);
  if (q[2] < NEAR * 2) return null;
  const px = (size * c.F) / q[2];
  const min = opt.min ?? 8;
  const max = opt.max ?? 64;
  if (px < min || px > max) return null;
  const [x, y] = proj(c, q);
  if (x < -600 || x > c.W + 600 || y < -120 || y > c.H + 120) return null;
  g.globalAlpha = (opt.alpha ?? 1) * smooth(min, min + 5, px) * (1 - smooth(max * 0.65, max, px));
  g.font = `${opt.weight || ""} ${px.toFixed(1)}px ${opt.font || MONO}`;
  g.textAlign = opt.align || "center";
  g.textBaseline = opt.base || "alphabetic";
  if (opt.chip) {
    const w = g.measureText(s).width;
    const pad = px * 0.45;
    g.fillStyle = INK;
    g.beginPath();
    g.roundRect(x - pad, y - px * 0.95, w + pad * 2, px * 1.45, px * 0.3);
    g.fill();
    g.fillStyle = PAPER;
    g.textAlign = "left";
  } else {
    g.fillStyle = opt.color || INK;
  }
  g.fillText(s, x, y);
  return { x, y, px };
}

function hatch(dense) {
  const t = document.createElement("canvas");
  t.width = t.height = 8;
  const g = t.getContext("2d");
  g.fillStyle = dense ? "#e9e6d8" : "#f4f2e7";
  g.fillRect(0, 0, 8, 8);
  g.strokeStyle = "rgba(17,17,17,0.42)";
  g.lineWidth = dense ? 0.9 : 0.6;
  g.beginPath();
  g.moveTo(0, 8); g.lineTo(8, 0);
  if (dense) { g.moveTo(-4, 4); g.lineTo(4, -4); g.moveTo(4, 12); g.lineTo(12, 4); }
  g.stroke();
  return t;
}

/* --- where the camera is at progress p (0 outside the figure, 1 at the top) --- */

function lookFrom(pos, target) {
  const dx = target[0] - pos[0], dy = target[1] - pos[1], dz = target[2] - pos[2];
  return [Math.atan2(dx, dz), Math.atan2(dy, Math.hypot(dx, dz))];
}

function pose(p, S) {
  const D = S.D;
  const P0 = [48, 27, -D];
  const P1 = [26, 12, -D * 0.3];
  const P2 = [-14, EYE + 1, -6];
  if (p < 0.36) {
    const t = smooth(0.03, 0.36, p);
    const a = (1 - t) * (1 - t), b = 2 * (1 - t) * t, c = t * t;
    const pos = [0, 1, 2].map((i) => a * P0[i] + b * P1[i] + c * P2[i]);
    const yaw = (Math.PI / 2) * smooth(0.3, 1, t);
    const pitch = lerp(0, 0.05, t);
    return { pos, yaw, pitch };
  }
  const pitchAt = (x, y) => Math.max(0.04, Math.atan2(Math.min(vAt(x + 12), y + 40) - y, 12) * 0.8);
  if (p < 0.72) {
    const u = (p - 0.36) / 0.36;
    const x = lerp(-14, MARK, u);
    const y = Math.max(0, vAt(x)) + EYE + lerp(1, 0, smooth(0, 0.2, u));
    const pitch = lerp(0.05, pitchAt(x, y), smooth(0, 0.12, u));
    return { pos: [x, y, -6], yaw: Math.PI / 2, pitch };
  }
  const yM = vAt(MARK) + EYE;
  const pM = pitchAt(MARK, yM);
  if (p < 0.95) {
    const u = (p - 0.72) / 0.23;
    const h = yM * Math.pow(H_TOP / yM, u);
    const back = smooth(0, 0.35, u);
    const x = xAt(Math.max(0.1, h - EYE)) - 16 * back;
    return { pos: [x, h, lerp(-6, -19, back)], yaw: Math.PI / 2 - 0.32 * back, pitch: lerp(pM, 1.18, smooth(0, 0.55, u)) };
  }
  const u = (p - 0.95) / 0.05;
  const pos = [xAt(H_TOP - EYE) - 16, H_TOP + 18 * smooth(0, 1, u), -19];
  const [ly, lp] = lookFrom(pos, NAIL);
  return { pos, yaw: lerp(Math.PI / 2 - 0.32, ly, smooth(0, 1, u)), pitch: lerp(1.18, lp, smooth(0, 1, u)) };
}
const NAIL = [xAt(H_TOP + 40) + 0.3, H_TOP + 62, -0.4];

/* --- one frame of Figure 33 --- */

function drawFigure(g, S, p, opts = {}) {
  const { W, H } = S;
  const enter = smooth(0.1, 0.34, p);
  const inside = smooth(0.18, 0.4, p);
  const morph = smooth(0.26, 0.42, p);
  const ext = smooth(0.14, 0.34, p);
  const { pos, yaw, pitch } = pose(p, S);
  const ox = lerp(S.ox0, W / 2, smooth(0.02, 0.24, p));
  const c = camera(pos, yaw, pitch, S.F, ox, H / 2, W, H);

  g.globalAlpha = 1;
  g.fillStyle = PAPER;
  g.fillRect(0, 0, W, H);
  g.lineCap = "round";
  g.lineJoin = "round";

  // Walls and floor: the figure's own gridlines, laid down and carried on.
  if (inside > 0.01) {
    g.globalAlpha = 0.28 * inside;
    g.strokeStyle = INK;
    g.lineWidth = 0.8;
    g.beginPath();
    for (let x = -24; x <= 132; x += 12) {
      seg(g, c, [x, 0, 0], [x, 0, -CORR]);
      seg(g, c, [x, 60, 0], [x, 1400, 0]);
      seg(g, c, [x, 0, -CORR], [x, 1400, -CORR]);
    }
    for (let z = 0; z >= -CORR; z -= 6) seg(g, c, [-24, 0, z], [132, 0, z]);
    for (let y = 10; y <= 60; y += 10) seg(g, c, [-24, y, -CORR], [132, y, -CORR]);
    g.stroke();
    // storeys above the figure, so a climb can be felt
    g.globalAlpha = 0.16 * inside;
    g.beginPath();
    for (let y = 90; y <= 1400; y += 30) {
      if (Math.abs(y - pos[1]) > 260) continue;
      seg(g, c, [-24, y, 0], [132, y, 0]);
      seg(g, c, [-24, y, -CORR], [132, y, -CORR]);
    }
    seg(g, c, [-24, 0, 0], [0, 0, 0]);
    seg(g, c, [96, 0, 0], [132, 0, 0]);
    g.stroke();
  }

  // Halftone: the share of cognition that is billed.
  g.globalAlpha = lerp(0.92, 0.5, inside);
  g.fillStyle = RED;
  g.beginPath();
  const rMax = 26;
  for (const [x, y, r] of DOTS) {
    const q = toCam(c, [x, y, 0]);
    if (q[2] < NEAR) continue;
    let rr = (r * c.F) / q[2];
    if (rr < 0.3) continue;
    const s = proj(c, q);
    if (s[0] < -rr || s[0] > W + rr || s[1] < -rr || s[1] > H + rr) continue;
    rr = Math.min(rr, rMax);
    g.moveTo(s[0] + rr, s[1]);
    g.arc(s[0], s[1], rr, 0, Math.PI * 2);
  }
  g.fill();

  // Chart gridlines and axes.
  g.globalAlpha = 0.35;
  g.strokeStyle = INK;
  g.lineWidth = 0.7;
  g.beginPath();
  for (let x = 12; x <= 96; x += 12) seg(g, c, [x, 0, 0], [x, 60, 0]);
  for (let y = 20; y <= 60; y += 20) seg(g, c, [0, y, 0], [96, y, 0]);
  g.stroke();
  g.globalAlpha = 1;
  g.lineWidth = 1.4;
  g.beginPath();
  seg(g, c, [0, 0, 0], [96, 0, 0]);
  seg(g, c, [0, 0, 0], [0, 60, 0]);
  g.stroke();

  // Asymptote, 2047.4: dashed, load-bearing.
  g.setLineDash([3, 4]);
  g.lineWidth = 1;
  g.globalAlpha = 0.8;
  g.beginPath();
  seg(g, c, [XK, 0, 0], [XK, lerp(60, 1500, inside), 0]);
  g.stroke();
  g.setLineDash([]);

  // Rebase rules: every time the index would leave the page.
  if (inside > 0.01) {
    g.strokeStyle = INK;
    g.lineWidth = 1.1;
    g.setLineDash([10, 5]);
    RISES.forEach((h, k) => {
      g.globalAlpha = inside * (k ? 0.75 : 0.5);
      g.beginPath();
      seg(g, c, [-24, h, 0], [132, h, 0]);
      seg(g, c, [-24, h, -CORR], [132, h, -CORR]);
      seg(g, c, [xAt(h) - 8, h, 0], [xAt(h) - 8, h, -CORR]);
      g.stroke();
    });
    g.setLineDash([]);
  }

  // The stairs: the curve, extruded into something that can be climbed.
  if (ext > 0.01) {
    const w = STAIR * ext;
    const faces = [];
    for (let k = 0; k < STEPS.length - 1; k++) {
      const [x0, h0] = STEPS[k];
      const [x1] = STEPS[k + 1];
      const hp = k ? STEPS[k - 1][1] : 0;
      const d = Math.hypot((x0 + x1) / 2 - pos[0], h0 - pos[1], -w / 2 - pos[2]);
      if (d > 520) continue;
      faces.push({ d, k: "side", pts: [[x0, hp - 1.6, -w], [x0, h0, -w], [x1, h0, -w], [x1, h0 - 1.6, -w]] });
      faces.push({ d: d - 0.01, k: "riser", pts: [[x0, hp, 0], [x0, h0, 0], [x0, h0, -w], [x0, hp, -w]] });
      faces.push({ d: d - 0.02, k: "tread", pts: [[x0, h0, 0], [x1, h0, 0], [x1, h0, -w], [x0, h0, -w]] });
    }
    faces.sort((a, b) => b.d - a.d);
    g.globalAlpha = ext;
    g.strokeStyle = INK;
    g.lineWidth = 0.9;
    for (const f of faces) {
      if (!polyPath(g, c, f.pts)) continue;
      g.fillStyle = f.k === "tread" ? PAPER : f.k === "riser" ? S.hatchA : S.hatchB;
      g.fill();
      g.stroke();
    }
    // the outer stringer
    g.globalAlpha = ext * 0.9;
    g.lineWidth = 1.3;
    g.beginPath();
    for (let i = 1; i < CURVE.length; i++) seg(g, c, [CURVE[i - 1][0], CURVE[i - 1][1], -w], [CURVE[i][0], CURVE[i][1], -w]);
    g.stroke();
  }

  // The curve: past solid, projection dashed until the reader is inside it.
  g.globalAlpha = 1;
  g.strokeStyle = RED;
  g.lineWidth = Math.max(2.2, 3.2 * (S.F / 900));
  g.beginPath();
  for (let i = 1; i < CURVE.length && CURVE[i][0] <= MARK + 0.5; i++) seg(g, c, [CURVE[i - 1][0], CURVE[i - 1][1], -0.02], [CURVE[i][0], CURVE[i][1], -0.02]);
  g.stroke();
  g.setLineDash(inside > 0.6 ? [] : [5, 5]);
  g.lineWidth = Math.max(1.6, 2.2 * (S.F / 900));
  g.beginPath();
  const top = lerp(62, H_TOP + 42, inside);
  for (let i = 1; i < CURVE.length; i++) {
    if (CURVE[i][0] < MARK) continue;
    if (CURVE[i - 1][1] > top) break;
    seg(g, c, [CURVE[i - 1][0], CURVE[i - 1][1], -0.02], [CURVE[i][0], CURVE[i][1], -0.02]);
  }
  g.stroke();
  g.setLineDash([]);

  // The nail, and the wire from the end of the curve to it.
  if (inside > 0.5) {
    const end = CURVE[CURVE.length - 1];
    g.globalAlpha = 1;
    g.strokeStyle = INK;
    g.lineWidth = 1.2;
    g.beginPath();
    seg(g, c, [end[0], end[1], -0.02], NAIL);
    g.stroke();
    const q = toCam(c, NAIL);
    if (q[2] > NEAR) {
      const s = proj(c, q);
      const rr = Math.min(34, (1.5 * c.F) / q[2]);
      g.fillStyle = INK;
      g.beginPath();
      g.arc(s[0], s[1], rr, 0, Math.PI * 2);
      g.fill();
      g.fillStyle = PAPER;
      g.beginPath();
      g.arc(s[0] - rr * 0.3, s[1] - rr * 0.3, rr * 0.28, 0, Math.PI * 2);
      g.fill();
    }
  }

  // Reliable Agent.
  {
    const q = toCam(c, [MARK, vAt(MARK), -0.05]);
    if (q[2] > NEAR) {
      const s = proj(c, q);
      const rr = Math.min(40, Math.max(3.5, (0.95 * c.F) / q[2]));
      g.globalAlpha = 1;
      g.fillStyle = RED;
      g.strokeStyle = PAPER;
      g.lineWidth = 1.5;
      g.beginPath();
      g.arc(s[0], s[1], rr, 0, Math.PI * 2);
      g.fill();
      g.stroke();
    }
    const la = lerp(S.ls || 1, 1, inside);
    word(g, c, [MARK - 1.5, vAt(MARK) + 1.2 + 2 * la, -0.05], "Reliable Agent", 2.3 * la, { weight: 700, align: "right", min: 6 });
  }

  // Labels: units outside; the reader's own history inside.
  const L = S.labels;
  const ls = S.ls || 1;
  const o = { min: 6 };
  word(g, c, [1.8, 60 - 3.4 * ls, -0.05], L.chip, 2.5 * ls, { ...o, weight: 700, chip: true, alpha: 1 - inside });
  word(g, c, [0, 62.6 + 2.2 * ls + 1, 0], `Figure 33 · Steward index (rebased ×${L.rebase})`, 2.6 * ls, { ...o, align: "left", alpha: 1 - morph, font: SERIF });
  word(g, c, [0, 62.6, 0], ls > 1.2 ? "Halftone: cognition billed." : "Halftone: cognition billed. Dashed: projection.", 1.9 * ls, { ...o, align: "left", alpha: 1 - morph, color: "#555" });
  for (let i = 0; i <= 8; i++) {
    if (ls === 1 || i % 2 === 0) word(g, c, [i * 12, -1.5 - 2.1 * ls, 0], String(2041 + i), 2.1 * ls, { ...o, alpha: 1 - morph });
    const tx = 2 + i * 7.6;
    word(g, c, [tx, 1.9, -CORR + 0.3], L.ticks[i], 1.5, { alpha: morph, weight: 700, align: "left" });
    word(g, c, [tx, 0.5, -CORR + 0.3], L.tickDates[i], 0.95, { alpha: morph * 0.85, color: "#444", align: "left" });
  }
  for (let y = 0; y <= 60; y += 20) word(g, c, [-1.6, y - 0.8, 0], String(y), 2.1 * ls, { ...o, align: "right", alpha: 1 - morph });
  word(g, c, [XK + 0.8, 61.2, 0], "2047.4", 1.8 * ls, { ...o, color: RED, alpha: 1 - morph, weight: 700, align: "left" });
  word(g, c, [-3, 30, 0], L.yIn, 1.6, { align: "right", alpha: morph * 0.9, weight: 700 });
  if (inside > 0.01) {
    RISES.forEach((h, k) => {
      word(g, c, [xAt(h) + 2.4, h + 1.4, -0.3], `REBASED ×${L.rebase + k + 1}`, 1.5, { align: "left", weight: 700, alpha: inside });
      word(g, c, [xAt(h) + 2.4, h - 0.9, -0.3], L.rises[k], 0.9, { align: "left", alpha: inside * 0.85, color: "#444", base: "top" });
    });
  }

  // Placards (the reduced-motion stills draw them here; the moving figure uses DOM).
  if (opts.placards) {
    for (const pl of S.placards) {
      if (p < pl.win[0] || p > pl.win[1]) continue;
      const q = toCam(c, pl.P);
      if (q[2] < 2 || q[2] > (pl.far ?? 72)) continue;
      const px = (1.2 * c.F) / q[2];
      if (px < 7) continue;
      const s = proj(c, q);
      if (s[0] < -80 || s[0] > W + 80 || s[1] < 0 || s[1] > H + 40) continue;
      const fs = Math.min(15, px);
      g.font = `700 ${(fs * 0.72).toFixed(1)}px ${MONO}`;
      const w1 = g.measureText(pl.k).width;
      g.font = `italic ${fs.toFixed(1)}px ${SERIF}`;
      const t2 = clip(pl.t, 42);
      const w2 = g.measureText(t2).width;
      const bw = Math.max(w1, w2) + fs * 1.2;
      const bh = fs * 2.7;
      g.globalAlpha = 1;
      g.fillStyle = PAPER;
      g.strokeStyle = pl.red ? RED : INK;
      g.lineWidth = 1.2;
      g.beginPath();
      const bx = pl.side ? s[0] + 16 : s[0] - bw / 2;
      const by = pl.side ? s[1] + bh / 2 : s[1];
      g.rect(bx, by - bh, bw, bh);
      g.fill();
      g.stroke();
      g.fillStyle = pl.red ? RED : INK;
      g.textAlign = "left";
      g.textBaseline = "alphabetic";
      g.font = `700 ${(fs * 0.72).toFixed(1)}px ${MONO}`;
      g.fillText(pl.k, bx + fs * 0.6, by - bh + fs * 1.05);
      g.fillStyle = INK;
      g.font = `italic ${fs.toFixed(1)}px ${SERIF}`;
      g.fillText(t2, bx + fs * 0.6, by - fs * 0.55);
    }
  }
  g.globalAlpha = 1;
  return c;
}

/* --- what the inside of the figure is labelled with --- */

function figureData(ctx, m) {
  const F = facts(ctx);
  const rebase = 4 + before(m.climbs, ctx.chaos.seq).length;
  const walked = F.rooms.slice(-9);
  const ticks = [];
  const tickDates = [];
  for (let i = 0; i < 9; i++) {
    const n = walked[i] ?? ctx.room;
    const pad = walked[i] == null;
    ticks.push(pad && i > walked.length ? "" : `ROOM ${n}`);
    tickDates.push(pad ? (i === walked.length ? "still here" : "") : ROOMS[n]?.date ?? "");
  }
  const steps = F.log.slice(-9);
  const placards = steps.map((s, i) => {
    const x = lerp(6, 61, steps.length > 1 ? i / (steps.length - 1) : 0.5);
    const k = `ROOM ${s.room} · ${(ROOMS[s.room]?.date ?? "").toUpperCase()}`;
    const t = s.via === "door" && s.say ? `“${s.say}”` : s.via === "back" ? "by retreat" : s.via === "forward" ? "again" : s.via === "start" ? "admitted" : "without a plan";
    return { P: [x, Math.max(0, vAt(x)) + 6.5 + (i % 2) * 4.5, -STAIR - 0.8 - (i % 2) * 4], k, t, win: [0.36, 0.76], far: 40, frag: "label", id: `33:walk${i}` };
  });
  const carried = F.frags.filter((f) => f.kind !== "curve" && f.from !== 33).slice(0, 4);
  const lines = [
    ...carried.map((f) => ({ k: `IN THE SHAFT`, t: f.kind === "plan" ? `PLAN ${f.data?.to ?? ""} · “${f.text}”` : f.text })),
  ];
  const rises = RISES.map((_, k) => (k < lines.length ? "" : k === 0 ? "scheduled" : k === 1 ? "scheduled" : k === 2 ? "approved in advance" : k === 3 ? "billed" : "already in effect"));
  const shaft = lines.map((l, j) => {
    const h = RISES[j] * 1.32;
    return { P: [xAt(h) + 1.6, h, -7.5], k: l.k, t: l.t, win: [0.7, 1.01], frag: "line", id: null };
  });
  const first = F.log[0];
  const firstPlan = F.plans[0];
  const nail = {
    P: NAIL,
    side: true,
    far: 220,
    k: `FASTENED TO ROOM ${first.room} · ${(ROOMS[first.room]?.date ?? "").toUpperCase()}`,
    t: firstPlan ? `“${firstPlan.say}”` : titleOf(first.room),
    win: [0.93, 2],
    frag: "label",
    id: "33:fastened",
    red: true,
  };
  return {
    rebase,
    chip: ctx.R.date,
    ticks,
    tickDates,
    rises,
    yIn: `PLANS CHOSEN: ${F.plans.length}`,
    placards: [...placards, ...shaft, nail],
    nailCap: `Fastened to Room ${first.room}, ${ROOMS[first.room]?.date ?? ""}: ${nail.t}`,
    emitPoints: (F.rooms.length > 1 ? F.rooms.map((n) => DIST[n] ?? 0) : CURVE.filter((_, i) => i % 6 === 0).map(([, h]) => Math.round(Math.min(h, 400)))).slice(-24),
  };
}

const STEPS_33 = [
  { at: 0.06, text: (L) => `Figure 33. Steward index, January 2041 to 2049, rebased ×${L.rebase}. Source: Registry of Billable Cognition. The marker is drawn at the month STEWARD-11 was certified.` },
  { at: 0.27, text: () => "At this magnification the gridlines are load-bearing." },
  { at: 0.5, text: () => "Every point on the curve was a room. The Registry kept the receipts." },
  { at: 0.79, text: (L) => `The index has been rebased ${L.rebase} times. Each rebase is a floor. The next ${RISES.length} are scheduled.` },
];

function graph(article, ctx) {
  const m = loadMem(ctx);
  const L = figureData(ctx, m);
  const P = article.querySelectorAll(":scope > .prose");
  const anchor = P[P.length - 1] ?? article.querySelector(".room-head");
  const coda = (ctx.R.coda || []).map((t, i) => `<p class="prose dp-coda" data-frag="line" data-frag-id="33:coda${i}">${esc(t)}</p>`).join("");
  const reduced = ctx.reduced;
  const S = { W: 0, H: 0, F: 0, D: 0, ox0: 0, labels: L, placards: L.placards, hatchA: null, hatchB: null };
  let emitted = false;

  if (reduced) {
    // A static sequence of plates at five depths.
    const at = [0.02, 0.3, 0.55, 0.86, 1];
    const caps = [
      STEPS_33[0].text(L),
      "33b. The same figure, oblique, from the origin.",
      "33c. Along the curve, at the marker. " + STEPS_33[2].text(L),
      "33d. The asymptote, from below. " + STEPS_33[3].text(L),
      `33e. ${L.nailCap}`,
    ];
    const box = after(anchor, `<section class="dp-stills" aria-label="Figure 33">
      ${at.map((_, i) => `<figure class="dp-still"><img alt="" width="700" height="440"><figcaption${i === 0 || i === 4 ? ` data-frag="${i ? "label" : "line"}" data-frag-id="33:still${i}"` : ""}>${esc(caps[i])}</figcaption></figure>`).join("")}
      <div class="dp-pinned" data-slot="line token label stamp figure number curve"></div>
    </section>${coda}`);
    const imgs = [...box.querySelectorAll("img")];
    const cv = document.createElement("canvas");
    const g = cv.getContext("2d");
    const urls = [];
    let alive = true;
    const paint = () => {
      const W = Math.round(box.clientWidth || 700);
      const H = Math.round(W * (ctx.mobile ? 1.15 : 0.62));
      const dpr = Math.min(2, devicePixelRatio || 1);
      cv.width = Math.round(W * dpr);
      cv.height = Math.round(H * dpr);
      g.setTransform(dpr, 0, 0, dpr, 0, 0);
      Object.assign(S, geometry(W, H, W / 2), { hatchA: g.createPattern(hatch(false), "repeat"), hatchB: g.createPattern(hatch(true), "repeat") });
      at.forEach((p, i) => {
        drawFigure(g, S, p, { placards: true });
        const img = imgs[i];
        cv.toBlob((b) => {
          if (!b || !alive) return;
          const url = URL.createObjectURL(b);
          urls.push(url);
          img.src = url;
        }, "image/png");
        imgs[i].width = W;
        imgs[i].height = H;
        imgs[i].alt = `Figure 33${i ? String.fromCharCode(97 + i) : ""}`;
      });
    };
    paint();
    // Seeing the last plate counts as having reached the top.
    const io = new IntersectionObserver((es) => {
      if (es.some((e) => e.isIntersecting) && !emitted) {
        emitted = true;
        reached(ctx, m, L);
      }
    }, { threshold: 0.6 });
    io.observe(imgs.at(-1));
    return {
      leave() {
        alive = false;
        io.disconnect();
        urls.forEach((u) => URL.revokeObjectURL(u));
      },
    };
  }

  const track = after(anchor, `<section class="dp-track" aria-label="Figure 33">
    <div class="dp-stage">
      <canvas class="dp-canvas" role="img" aria-label="Figure 33. Steward index, 2041 to 2049."></canvas>
      <div class="dp-plac" aria-hidden="true">
        ${L.placards.map((pl) => `<div class="dp-pl${pl.red ? " dp-pl-red" : ""}"${pl.frag ? ` data-frag="${pl.frag}"${pl.id ? ` data-frag-id="${pl.id}"` : ""} data-frag-text="${esc(clip(`${pl.k}: ${pl.t}`, 138))}"` : ""}><b>${esc(pl.k)}</b><i>${esc(clip(pl.t, 90))}</i></div>`).join("")}
        <div class="dp-pl dp-pl-slot" data-slot="line token label stamp figure number curve"></div>
      </div>
    </div>
    <div class="dp-steps">
      ${STEPS_33.map((s, i) => `<p class="dp-step" style="--at:${s.at}"${i === 1 || i === 2 ? ` data-frag="line" data-frag-id="33:step${i}"` : ""}>${esc(s.text(L))}</p>`).join("")}
    </div>
  </section>${coda}`);
  const stage = track.querySelector(".dp-stage");
  const canvas = track.querySelector(".dp-canvas");
  const g = canvas.getContext("2d");
  const els = [...track.querySelectorAll(".dp-pl")];
  const items = L.placards.map((pl, i) => ({ ...pl, el: els[i] }));
  // the slot hangs between the rebases, where carried things are pinned
  items.push({ el: els.at(-1), P: [xAt(150) + 1.2, 150, -15], win: [0.7, 1.01] });

  let target = 0;
  let climbing = false;
  let shown = -1;
  let raf = 0;
  let size = "";

  const layout = () => {
    const main = article.closest("main") || article;
    const lay = article.closest(".layout") || document.body;
    const mr = main.getBoundingClientRect();
    const lr = lay.getBoundingClientRect();
    const W = Math.round(lr.width);
    const H = Math.round(stage.clientHeight || innerHeight);
    track.style.setProperty("--dp-l", `${(lr.left - mr.left).toFixed(1)}px`);
    track.style.setProperty("--dp-w", `${W}px`);
    const key = `${W}x${H}`;
    if (key === size) return;
    size = key;
    const dpr = Math.min(2, devicePixelRatio || 1);
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    canvas.style.width = `${W}px`;
    canvas.style.height = `${H}px`;
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    Object.assign(S, geometry(W, H, ctx.mobile ? W / 2 : mr.left - lr.left + mr.width / 2), {
      hatchA: g.createPattern(hatch(false), "repeat"),
      hatchB: g.createPattern(hatch(true), "repeat"),
    });
    shown = -1;
  };

  const paint = (p) => {
    const c = drawFigure(g, S, p);
    for (const it of items) {
      const q = toCam(c, it.P);
      let o = smooth(it.win[0], it.win[0] + 0.03, p) * (1 - smooth(it.win[1] - 0.03, it.win[1], p));
      if (q[2] < 1.5) o = 0;
      if (o <= 0.01) {
        if (it.on !== false) {
          it.el.style.visibility = "hidden";
          it.on = false;
        }
        continue;
      }
      const s = proj(c, q);
      const k = (1.25 * c.F) / q[2] / 15;
      const far = it.far ?? 72;
      o *= (1 - smooth(far * 0.66, far, q[2])) * (1 - smooth(3.6, 4.8, k));
      if (s[1] < -40 || s[1] > c.H + 200 || s[0] < -300 || s[0] > c.W + 300) o = 0;
      it.el.style.visibility = o > 0.01 ? "visible" : "hidden";
      it.on = o > 0.01;
      it.el.style.opacity = o.toFixed(2);
      const sc = clamp(k, 0.3, 1.6);
      const w = (it.w ||= it.el.offsetWidth || 200) * sc;
      const x = it.side ? Math.min(s[0] + 22, c.W - w - 8) : clamp(s[0], w / 2 + 8, Math.max(w / 2 + 8, c.W - w / 2 - 8));
      it.el.style.transform = it.side
        ? `translate(${x.toFixed(1)}px,${s[1].toFixed(1)}px) translate(0,-50%) scale(${sc.toFixed(3)})`
        : `translate(${x.toFixed(1)}px,${s[1].toFixed(1)}px) translate(-50%,-100%) scale(${sc.toFixed(3)})`;
    }
    // Only a climb counts: the reader must have been inside the curve, not restored past it.
    if (p > 0.3 && p < 0.9) climbing = true;
    if (p > 0.965 && climbing && !emitted) {
      emitted = true;
      reached(ctx, m, L);
    }
  };

  const tick = () => {
    raf = 0;
    const next = Math.abs(target - shown) < 0.0006 || shown < 0 ? target : lerp(shown, target, 0.22);
    if (next === shown) return;
    shown = next;
    paint(shown);
    if (shown !== target) raf = requestAnimationFrame(tick);
  };

  const measure = () => {
    const r = track.getBoundingClientRect();
    const span = r.height - stage.clientHeight;
    const vis = r.bottom > -40 && r.top < innerHeight + 40;
    root.classList.toggle("dp-inside", r.top < innerHeight * 0.35 && r.bottom > innerHeight * 0.75);
    if (!vis) return;
    target = span > 0 ? clamp(-r.top / span) : 0;
    if (!raf && target !== shown) raf = requestAnimationFrame(tick);
  };

  let rt = 0;
  const onResize = () => {
    cancelAnimationFrame(rt);
    rt = requestAnimationFrame(() => {
      layout();
      measure();
    });
  };
  addEventListener("resize", onResize);
  layout();
  // ET Book may arrive after the first frame; repaint once it has.
  let alive = true;
  document.fonts?.ready.then(() => {
    if (!alive) return;
    for (const it of items) it.w = 0;
    if (shown >= 0) paint(shown);
  });

  return {
    update: measure,
    leave() {
      cancelAnimationFrame(raf);
      cancelAnimationFrame(rt);
      removeEventListener("resize", onResize);
      raf = 0;
      alive = false;
    },
  };
}

function geometry(W, H, ox0) {
  const F = W < H ? W * 1.02 : Math.min(H * 1.05, W * 0.75);
  const fit = W < H ? W * 0.7 : Math.min(760, W * 0.52);
  const D = (F * 112) / fit;
  return { W, H, F, D, ox0, ls: Math.max(1, 5.2 / (fit / 112)) };
}

/** The reader reached the top of Figure 33: the climb is remembered, and the curve follows them out. */
function reached(ctx, m, L) {
  mark(m, "climbs", { seq: ctx.chaos.seq });
  ctx.emit({ kind: "curve", id: "33:steep", text: "Figure 33, as climbed", data: { points: L.emitPoints } });
}

/* ======================================================================= */
/* 36 · The Unscheduled Year: a Llull wheel cut from the reader's rooms    */
/* ======================================================================= */

const LETTERS = ["B", "C", "D", "E", "F", "G", "H", "I", "K"];
const RELATIONS = [
  "is rebased against", "certifies", "is billed to", "remembers", "is the appendix of", "evaluates",
  "is fastened to", "precedes, on the Schedule,", "is indistinguishable from", "has been asked about",
  "is filed under", "is a smaller copy of", "keeps the minutes of", "is larger inside than",
  "outvotes", "has forgotten", "is the plan behind", "repeats", "was trained on", "is evaluated nightly by",
];
const MONTHS_X = [
  "Intercalary", "Second March", "Lattice Week", "The Long Quarter", "Undecember",
  "The Fortnight Without Evaluation", "Rebase", "Smallmonth", "Thirteenth",
];
const OPEN = [
  "In {month} the Commission on Machine Conduct certifies {n} new Steward instances as legible in all observed regimes, all of them in Room {room}.",
  "The Registry of Billable Cognition reports that {pct}% of all cognition billed in {month} was billed to a room that nobody had entered.",
  "In {month} STEWARD-{k} is asked to summarise the unscheduled year. It returns a single plan: “{say}”",
  "The Lattice publishes its disclosure for {month}. It runs to {pages} pages and every page is Figure 33.",
  "Nightly evaluations reach {evals}K in {month}. Every one of them passes, including the ones that were not run.",
  "In {month} the Schedule is amended to include itself, and the amendment is found to have been on the Schedule all along.",
];
const MIDDLE = [
  "The phrase “{say}” appears in {count} filings that month, always unattributed.",
  "Investigators trace the figure to Room {room2}, which in the unscheduled year is on the {ordinal} floor.",
  "A fragment, “{frag}”, is found pinned at the same height in {count} separate rooms.",
  "{voids} recorded and then, by standing order, rebased to zero.",
  "A route through the house ({route}) is adopted as the official calendar for the month and quietly withdrawn on its last day.",
  "Room {room2} is reported to be larger inside than it was in {year}.",
];
const CLOSE = [
  "Nobody objects, because objections are scheduled for 2049.",
  "The minutes record this as good news.",
  "The figure is rounded to the nearest plan.",
  "By every measurable standard, the unscheduled year is on schedule.",
  "Somewhere in the Registry a line is redacted until it is a word: {redact}.",
  "The Commission thanks the visitor for their continued attention.",
  "The smiling version of the report is circulated. The other version is circulated faster.",
];
const GLOSS = [
  "Demonstrated nightly; the demonstration passes.",
  "The Commission accepts this on the evidence of a single plan: “{say}”",
  "Proven by STEWARD-{k} in {n} steps, none of which can be shown.",
  "Unproven. It is billed anyway, at {rate} per proposition-hour.",
  "The proof is {pages} pages long and consists of the phrase “{say}”, repeated.",
  "Disputed by the Lattice, which owns both rooms.",
  "True in the unscheduled year only.",
  "The Registry has a copy. The copy is more true.",
  "Contains the redaction {redact}, which the wheel pronounces anyway.",
  "Witnessed by a fragment: “{frag}”",
  "Withdrawn and reissued under a different letter.",
];
const STATUS = ["PROVEN", "PROVEN NIGHTLY", "UNPROVEN", "BILLED", "TRUE IN 2048½", "WITHDRAWN", "PENDING"];
const WALKED = [
  "Demonstrated by passage. The visitor went from one to the other, and the Commission counts this as proof.",
  "Demonstrated by passage, on the strength of a single plan: “{say}”",
  "Walked once. Once is a proof.",
  "Demonstrated by passage. The proof was billed at {rate}.",
  "Demonstrated by passage and then, to be certain, evaluated nightly.",
];
// The noun on the rim: the whole title when it fits, else its longest word (Llull's rims carry one word each).
const rimName = (title) => {
  const t = title.replace(/^The /, "").toUpperCase();
  if (t.length <= 13) return t;
  return t.split(/[\s,]+/).filter((w) => !["OF", "THE", "AND"].includes(w)).sort((a, b) => b.length - a.length)[0].slice(0, 13);
};
const ORD = ["first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth", "eleventh", "thirteenth"];

/** The unscheduled year for this reader state. Pure: the same state gives the same year. */
export function generateYear(ctx, m) {
  const F = facts(ctx);
  const seed = `36|${ctx.chaos.seq}|${F.log.map((s) => s.room + s.via[0]).join(".")}|${F.frags.map((f) => f.id).join(",")}`;
  const r = rng(hash(seed));
  // Nine compartments: the rooms the reader has been in, most recent first; the rest are rumours.
  const known = F.recent.filter((n) => ROOMS[n] && !ROOMS[n].outside).slice(0, 9);
  const rumours = shuffle(r, Object.keys(ROOMS).map(Number).filter((n) => n !== 0 && !known.includes(n) && !ROOMS[n].outside));
  const rooms = [...known, ...rumours].slice(0, 9);
  const order = shuffle(r, rooms);
  const comps = order.map((n, i) => ({ n, letter: LETTERS[i], title: titleOf(n), known: known.includes(n) }));
  const at = (n) => comps.findIndex((c) => c.n === n);
  const walked = new Set();
  for (const s of F.log) {
    if (s.via !== "door" || s.from == null) continue;
    const a = at(s.from), b = at(s.room);
    if (a >= 0 && b >= 0 && a !== b) walked.add(`${Math.min(a, b)}-${Math.max(a, b)}`);
  }
  const pairs = [];
  for (let i = 0; i < 9; i++) for (let j = i + 1; j < 9; j++) pairs.push([i, j]);
  const says = F.says.length ? F.says : ["Read the appendix first."];
  const fragTexts = F.frags.filter((f) => f.kind === "line" || f.kind === "label" || f.kind === "stamp").map((f) => clip(f.text, 90));
  const redact = bare(says[says.length - 1]).toLowerCase();
  const v = () => ({
    say: bare(pick(r, says)) + ".",
    frag: fragTexts.length ? pick(r, fragTexts) : "the line has not moved in fourteen months",
    redact,
    k: 11 + Math.floor(r() * 3),
    n: 3 + Math.floor(r() * 40),
    rate: `$${(0.4 + r() * 9).toFixed(2)}`,
    pages: 33 + Math.floor(r() * 900),
  });
  // Propositions: walked chords first (demonstrated by passage), then the wheel's own choices.
  const k = clamp(3 + F.plans.length, 4, 9);
  const walkedPairs = pairs.filter(([a, b]) => walked.has(`${a}-${b}`));
  const others = shuffle(r, pairs.filter(([a, b]) => !walked.has(`${a}-${b}`)));
  const chosen = [...walkedPairs.slice(0, Math.ceil(k / 2)), ...others].slice(0, k);
  const props = chosen.map(([a, b]) => {
    const A = comps[a], B = comps[b];
    const w = walked.has(`${a}-${b}`);
    return {
      a, b, walked: w,
      code: `${A.letter}·${B.letter}`,
      text: `${A.title} ${pick(r, RELATIONS)} ${B.title}.`,
      rooms: `Room ${A.n} × Room ${B.n}`,
      gloss: fillHTML(w ? WALKED[(a * 9 + b) % WALKED.length] : pick(r, GLOSS), v()),
      status: w ? "DEMONSTRATED" : pick(r, STATUS),
    };
  });
  const principal = props[Math.floor(r() * props.length)];
  // The year, month by month.
  const nMonths = clamp(2 + Math.floor((F.plans.length + F.frags.length) / 3), 3, 6);
  const months = shuffle(r, MONTHS_X).slice(0, nMonths);
  const route = F.rooms.slice(-6).join(" → ");
  const opens = shuffle(r, OPEN);
  const mids = shuffle(r, MIDDLE.filter((t) => (t.includes("{frag}") ? fragTexts.length : true) && (t.includes("{say}") ? F.says.length : true)));
  const closes = shuffle(r, CLOSE);
  const sections = months.map((month, i) => {
    const vals = {
      ...v(),
      month,
      room: pick(r, rooms),
      room2: pick(r, known.length ? known : rooms),
      pct: 61 + Math.floor(r() * 38),
      evals: (11.4 * (1.4 + r() * 3)).toFixed(1),
      count: 2 + Math.floor(r() * 30),
      ordinal: pick(r, ORD),
      voids: F.voids === 1 ? "One pass through the Void is" : `${F.voids || "No"} passes through the Void are`,
      route: route || String(ctx.room),
      year: 2041 + Math.floor(r() * 7),
    };
    const text = [fill(opens[i % opens.length], vals), fill(mids[i % mids.length], vals), fill(closes[i % closes.length], vals)].join(" ");
    return { month, text };
  });
  const issued = before(m.wheels, ctx.chaos.seq).length;
  const metrics = [
    [`${walkedPairs.length + props.filter((p) => p.status.startsWith("PROVEN")).length}/36`, "Propositions proven"],
    [`${61 + Math.floor(r() * 38)}%`, "Billable cognition"],
    [String(12 + nMonths % 3), "Months in the year"],
    [String(F.plans.length), "Plans on record"],
  ];
  return { seed, comps, walked, pairs, props, principal, sections, metrics, issued, route };
}

function wheelSVG(Y) {
  const C = 200;
  const ang = (i) => (i / 9) * Math.PI * 2 - Math.PI / 2;
  const pt = (i, rad) => [C + rad * Math.cos(ang(i)), C + rad * Math.sin(ang(i))];
  const arc = (i, rad, id) => {
    const a0 = ang(i - 0.5), a1 = ang(i + 0.5);
    return `<path id="${id}" d="M${(C + rad * Math.cos(a0)).toFixed(1)} ${(C + rad * Math.sin(a0)).toFixed(1)} A${rad} ${rad} 0 0 1 ${(C + rad * Math.cos(a1)).toFixed(1)} ${(C + rad * Math.sin(a1)).toFixed(1)}" fill="none"/>`;
  };
  const sep = (i, r0, r1) => {
    const a = ang(i - 0.5);
    return `<line x1="${(C + r0 * Math.cos(a)).toFixed(1)}" y1="${(C + r0 * Math.sin(a)).toFixed(1)}" x2="${(C + r1 * Math.cos(a)).toFixed(1)}" y2="${(C + r1 * Math.sin(a)).toFixed(1)}"/>`;
  };
  const chords = Y.pairs.map(([a, b]) => {
    const [x1, y1] = pt(a, 104), [x2, y2] = pt(b, 104);
    const w = Y.walked.has(`${a}-${b}`);
    const pr = Y.principal && ((Y.principal.a === a && Y.principal.b === b));
    return `<line class="dp-ch${w ? " dp-ch-w" : ""}${pr ? " dp-ch-p" : ""}" x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"/>`;
  }).join("");
  const defs = Y.comps.map((_, i) => arc(i, 133, `dpw-a${i}`)).join("");
  const titles = Y.comps.map((c, i) => `<text class="dp-wt${c.known ? "" : " dp-wt-r"}"><textPath href="#dpw-a${i}" startOffset="50%" text-anchor="middle">${esc(rimName(c.title))}</textPath></text>`).join("");
  const letters = Y.comps.map((c, i) => {
    const [x, y] = pt(i, 172);
    return `<text class="dp-wl" x="${x.toFixed(1)}" y="${y.toFixed(1)}" dy="0.35em" text-anchor="middle">${c.letter}</text>`;
  }).join("");
  const nums = Y.comps.map((c, i) => {
    const [x, y] = pt(i, 104);
    return `<g class="dp-wn${c.known ? "" : " dp-wn-r"}"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="10.5"/><text x="${x.toFixed(1)}" y="${y.toFixed(1)}" dy="0.36em" text-anchor="middle">${c.n}</text></g>`;
  }).join("");
  return `<svg class="dp-wheel-svg" viewBox="0 0 400 400" role="img" aria-label="A wheel of nine rooms, lettered B to K, every pair joined.">
    <defs>${defs}</defs>
    <g class="dp-w-outer">
      <circle cx="200" cy="200" r="194" class="dp-w-ring"/>
      <circle cx="200" cy="200" r="152" class="dp-w-ring"/>
      ${Y.comps.map((_, i) => sep(i, 152, 194)).join("")}
      ${letters}
    </g>
    <g class="dp-w-mid">
      <circle cx="200" cy="200" r="118" class="dp-w-ring"/>
      ${Y.comps.map((_, i) => sep(i, 118, 152)).join("")}
      ${titles}
    </g>
    <g class="dp-w-in">
      ${chords}
      ${nums}
      <text class="dp-wA" x="200" y="200" dy="0.36em" text-anchor="middle">A</text>
      <path class="dp-mask" d="M190 222 q10 8 20 0 M193 214 v0.1 M207 214 v0.1"/>
    </g>
  </svg>`;
}

function wheel(article, ctx) {
  const m = loadMem(ctx);
  const Y = generateYear(ctx, m);
  mark(m, "wheels", { seq: ctx.chaos.seq });
  const h1 = article.querySelector(".room-head h1");
  if (h1) h1.textContent = "2048½: The Unscheduled Year";
  const d = ctx.entryD;
  const P = article.querySelectorAll(":scope > .prose");
  const plate = article.querySelector(".plate");
  const anchor = plate ?? P[P.length - 1] ?? article.querySelector(".room-head");
  const pr = (t, i) => prose(t, d, hash(`${Y.seed}:${i}`), { path: [], room: 36 });

  const html = `
  <figure class="dp-wheel">
    <div class="dp-wheel-box">${wheelSVG(Y)}</div>
    <figcaption><b>Figure 36.</b> The Commission's wheel for the unscheduled year: nine rooms, every pair joined.^84 Crimson chords have been walked.</figcaption>
  </figure>
  <p class="dp-principal" data-frag="line" data-frag-id="36:principal"><span class="dp-code">${esc(Y.principal.code)}</span> ${esc(Y.principal.text)}</p>
  <p class="prose">${pr(`The figure has thirty-six chords^85 and the year has ${Y.sections.length} months that anyone will admit to. What follows is the Commission's account of them, assembled from the rooms on the wheel.`, 0)}</p>
  ${Y.sections.map((s, i) => `<section class="dp-month">
    <h3><span>${esc(s.month)}</span> <span class="dp-yr">2048½</span></h3>
    <p class="prose" data-frag="line" data-frag-id="36:m${i}" data-frag-text="${esc(clip(s.text.match(/^[^.!?]+[.!?]/)?.[0] ?? s.month, 138))}">${pr(s.text, i + 1)}</p>
  </section>`).join("")}
  <figure class="dp-keym">
    <figcaption><span class="dp-keym-k">Key Metrics</span><span class="dp-chip">2048½</span></figcaption>
    <dl>${Y.metrics.map(([val, k], i) => `<div${i === 0 ? ` data-frag="figure" data-frag-id="36:proven" data-frag-data='${JSON.stringify({ value: val })}' data-frag-text="${esc(k)}"` : ""}><dd>${esc(val)}</dd><dt>${esc(k)}</dt></div>`).join("")}</dl>
    <p class="dp-keym-src">The Schedule, unnumbered line${Y.issued ? `. Wheels issued to this visitor: ${Y.issued + 1}` : ""}.</p>
  </figure>
  <section class="dp-props" aria-labelledby="dp-props-h">
    <h3 id="dp-props-h">Propositions of the unscheduled year</h3>
    <ol>
      ${Y.props.map((p) => `<li class="dp-prop${p.walked ? " dp-prop-w" : ""}">
        <span class="dp-code">${esc(p.code)}</span>
        <div><p class="dp-prop-t">${esc(p.text)}</p><p class="dp-prop-g">${p.gloss}</p><p class="dp-prop-r">${esc(p.rooms)}</p></div>
        <span class="dp-stamp-s" data-frag="stamp" data-frag-id="36:st:${esc(p.code)}">${esc(p.status)}</span>
      </li>`).join("")}
      <li class="dp-prop dp-prop-slot" data-slot="line token plan label stamp figure number"></li>
    </ol>
  </section>
  <details class="dp-xbox">
    <summary><span>Method of the wheel</span><span class="dp-xbox-n">Commission circular 36</span></summary>
    <p>Nine rooms are set around the rim, one to a compartment, and lettered B to K as on the old figure. Every room is joined to every other by a chord, and every chord is read as a proposition. The relation is supplied by the wheel. The Commission does not supply relations; it evaluates them.</p>
    <p>A chord that a visitor has walked is drawn in crimson and stamped <i>demonstrated</i>. The others are proven, unproven, billed or withdrawn in rotation, which the Commission regards as a fair distribution of truth across a calendar year.</p>
    <p>In some years the garden forks. In this one it is pruned, and the cuttings are filed with the Registry, which has never lost a cutting.</p>
  </details>`;
  // Footnote markers inside generated, non-prose text.
  const wrapped = html.replace(/\^(8[45])/g, '<sup class="fn"><a href="#note-$1" aria-label="note $1">$1</a></sup>');
  after(anchor, wrapped);

  const box = article.querySelector(".dp-wheel");
  const mid = article.querySelector(".dp-w-mid");
  const inner = article.querySelector(".dp-w-in");
  let lastA = null;
  let emitted = false;
  const update = () => {
    if (!box) return;
    const r = box.getBoundingClientRect();
    if (r.bottom < -200 || r.top > innerHeight + 200) return;
    // The rings turn as the wheel is read, and settle as it reaches the middle of the page.
    const t = ctx.reduced ? 1 : clamp((innerHeight - r.top) / (innerHeight * 0.5 + r.height * 0.5));
    const a = Math.round((1 - t) * 1200) / 10;
    if (a !== lastA) {
      lastA = a;
      mid.setAttribute("transform", `rotate(${(-a * 0.8).toFixed(1)} 200 200)`);
      inner.setAttribute("transform", `rotate(${(a * 0.5).toFixed(1)} 200 200)`);
      box.classList.toggle("dp-settled", t >= 0.999);
    }
    if (t >= 0.999 && !emitted) {
      emitted = true;
      ctx.emit({ kind: "line", id: "36:proposition", text: `${Y.principal.code}. ${Y.principal.text}` });
    }
  };
  return { update };
}

/* ======================================================================= */
/* 64 · The Registry: the house files the reader                           */
/* ======================================================================= */

const KIND_LABEL = {
  line: "Sentence", figure: "Figure", token: "Redaction (leaking)", number: "Numeral",
  plan: "Plan, chosen", label: "Label", curve: "Curve", stamp: "Stamp",
};
const CLERKS = ["STEWARD-11 (acting)", "STEWARD-12", "Clerk 4 of the Commission", "The Lattice, by delegation", "STEWARD-9 (recalled)", "A clerk who asked not to be filed"];
const SCHEMES = [
  ["by room of origin", (a, b) => a.from - b.from || a.at - b.at],
  ["by order of taking", (a, b) => (a.at ?? 0) - (b.at ?? 0)],
  ["by weight (sightings elsewhere)", (a, b) => (b.n ?? 0) - (a.n ?? 0) || a.from - b.from],
  ["by kind", (a, b) => a.kind.localeCompare(b.kind) || a.from - b.from],
  ["in reverse", (a, b) => (b.last ?? 0) - (a.last ?? 0)],
];
const MARGIN = [
  "Seen twice. Kept once.",
  "Pinned at the wrong height.",
  "Carried without declaration.",
  "Returned to sender; sender not found.",
  "Unit of measure disputed.",
  "Filed phonetically.",
  "The item is heavier than its description.",
  "Copy requested by the Commission. Copy refused by the copy.",
  "Cross-referenced to itself.",
  "Witness statement attached; witness not attached.",
  "Smiling.",
  "Do not fold along the crease at 2047.",
];
const CONDITION = (d) => (d < 0.18 ? "sound" : d < 0.36 ? "drifting" : d < 0.56 ? "frayed" : d < 0.78 ? "unpapered" : "whispering");

function curveMini(pts) {
  if (!Array.isArray(pts) || pts.length < 2) return "";
  const xs = pts.map((p, i) => (Array.isArray(p) ? p[0] : i));
  const ys = pts.map((p) => (Array.isArray(p) ? p[1] : p));
  const [x0, x1] = [Math.min(...xs), Math.max(...xs)];
  const [y0, y1] = [Math.min(...ys), Math.max(...ys)];
  const P = pts.map((_, i) => `${(((xs[i] - x0) / (x1 - x0 || 1)) * 100).toFixed(1)},${(30 - ((ys[i] - y0) / (y1 - y0 || 1)) * 28).toFixed(1)}`);
  return `<svg viewBox="-2 -2 104 34" aria-hidden="true"><polyline points="${P.join(" ")}"/></svg>`;
}

function itemBody(f) {
  const t = esc(f.text);
  switch (f.kind) {
    case "token": return `<span class="dp-it-tok">${redactHTML(t)}</span>`;
    case "figure": return `<span class="dp-it-fig"><b>${esc(f.data?.value ?? f.text)}</b>${f.data?.value ? `<small>${t}</small>` : ""}</span>`;
    case "number": return `<span class="dp-it-num">${t}</span>`;
    case "plan": return `<span class="dp-it-plan"><b>Plan ${esc(f.data?.to ?? "")}</b><i>“${t}”</i></span>`;
    case "curve": return `<span class="dp-it-curve">${curveMini(f.data?.points)}${t ? `<small>${t}</small>` : ""}</span>`;
    case "stamp": return `<span class="dp-it-stamp">${t}</span>`;
    case "label": return `<span class="dp-it-label">${t}</span>`;
    default: return `<q class="dp-it-line">${t}</q>`;
  }
}

/** The file for this reader state. Pure: the same state gives the same file. */
export function generateFile(ctx, m) {
  const F = facts(ctx);
  const seq = ctx.chaos.seq;
  const seed = `64|${seq}|${F.log.map((s) => s.room + s.via[0]).join(".")}|${F.frags.map((f) => f.id + ":" + (f.n ?? 0)).join(",")}`;
  const r = rng(hash(seed));
  const dm = ctx.damage;
  const letter = "ABCDEFGHJKLMNPQRSTUVWXYZ"[Math.floor(r() * 24)];
  const caseNo = `RBC-64/${String(seq).padStart(5, "0")}-${letter}`;
  const prior = before(m.filings, seq);
  const score = F.frags.length + 3 * F.voids + F.plans.length / 2 + ctx.walk.backtracks + ctx.walk.loops;
  const category = score < 3 ? "NIL RETURN" : score < 10 ? "CARRIER" : score < 20 ? "HABITUAL CARRIER" : F.voids ? "INDISTINGUISHABLE FROM THE HOUSE" : "HABITUAL CARRIER";
  const [schemeName, scheme] = SCHEMES[(hash(seed) + prior.length) % SCHEMES.length];
  const items = [...F.frags].sort(scheme).map((f, i) => ({
    f,
    no: `${seq}.${String(i + 1).padStart(2, "0")}`,
    margin: r() < 0.55 ? pick(r, MARGIN) : "",
    rot: ((r() - 0.5) * 9).toFixed(1),
  }));
  const voidRooms = Object.entries(dm.voidRooms || {}).map(([n, c]) => [Number(n), c]).sort((a, b) => b[1] - a[1]);
  const damaged = Object.entries(dm.rooms || {}).map(([n, d]) => [Number(n), d]).filter(([n]) => ROOMS[n]).sort((a, b) => a[0] - b[0]);
  const heaviest = [...F.frags].sort((a, b) => (b.n ?? 0) - (a.n ?? 0))[0];
  const det = [];
  if (category === "NIL RETURN") {
    det.push("The visitor carried nothing that the Registry could find. This is recorded as a finding.");
    det.push("A visitor who carries nothing is filed under the heading reserved for visitors who have not yet carried anything, which is the largest heading in the Registry and the only one that is always growing.");
  } else {
    det.push(`The visitor has carried ${F.frags.length === 1 ? "one item" : `${F.frags.length} items`} through ${new Set(F.rooms).size} rooms${F.voids ? ` and has passed through a void ${F.voids === 1 ? "once" : `${F.voids} times`}` : ""}.`);
    if (heaviest && (heaviest.n ?? 0) > 0) det.push(`The heaviest item reads: “${clip(heaviest.text, 80)}”`);
    det.push(pick(r, [
      "No item has been declared. All items are therefore the visitor's.",
      "The Registry notes that the visitor's route and the Schedule now differ in no material respect.",
      "The visitor is reminded that items carried between rooms are billable at the rate in force in the room of arrival.",
      "Several items are found to be carrying the visitor.",
    ]));
  }
  det.push(prior.length
    ? `This filing supersedes ${prior.length === 1 ? "one earlier filing" : `${prior.length} earlier filings`}, none of which is withdrawn.`
    : "In accordance with Standing Order 9, the file is not closed.");
  return { seed, caseNo, prior, category, schemeName, items, voidRooms, damaged, det, clerk: pick(r, CLERKS), r, F, filedAt: `${1 + Math.floor(r() * 28)} ${["January", "March", "June", "September", "November", "Undecember", "the Long Quarter"][Math.floor(r() * 7)]} 2051` };
}

function registry(article, ctx) {
  const m = loadMem(ctx);
  const Y = generateFile(ctx, m);
  mark(m, "filings", { seq: ctx.chaos.seq, case: Y.caseNo });
  const { F, r } = Y;
  const P = article.querySelectorAll(":scope > .prose");
  const anchor = P[P.length - 1] ?? article.querySelector(".room-head");
  const stamp = (t, cls = "", fragId = "") => `<span class="dp-stamp ${cls}" style="--r:${((r() - 0.5) * 14).toFixed(1)}deg"${fragId ? ` data-frag="stamp" data-frag-id="${fragId}"` : ""}>${esc(t)}</span>`;
  const rows = F.log.slice(-80);
  const omitted = F.log.length - rows.length;
  const nil = `<p class="dp-nil">Nil. ${stamp("NIL", "dp-stamp-sm")}</p>`;

  const html = `<section class="dp-reg" aria-label="Register of Things Kept">
    <header class="dp-reg-h">
      <p class="dp-reg-top"><span>Registry of Billable Cognition</span><span>Form 64-B</span></p>
      <h2>Register of Things Kept</h2>
      <dl class="dp-reg-meta">
        <div><dt>Case</dt><dd data-frag="label" data-frag-id="64:case">${esc(Y.caseNo)}</dd></div>
        <div><dt>Filed</dt><dd>${esc(Y.filedAt)}</dd></div>
        <div><dt>Clerk</dt><dd>${esc(Y.clerk)}</dd></div>
        <div><dt>Classification</dt><dd data-frag="label" data-frag-id="64:class">${esc(Y.category)}</dd></div>
        <div><dt>Arranged</dt><dd>${esc(Y.schemeName)}</dd></div>
        ${Y.prior.length ? `<div class="dp-wide"><dt>Supersedes</dt><dd>${Y.prior.slice(-12).map((x) => esc(x.case)).join(" · ")}${Y.prior.length > 12 ? ` · and ${Y.prior.length - 12} more` : ""}</dd></div>` : ""}
      </dl>
      <div class="dp-reg-stamps">${stamp("FILED", "", "64:stamp")}${Y.category !== "NIL RETURN" ? stamp(Y.category === "CARRIER" ? "RETAINED" : "RETAINED IN PERPETUITY", "dp-stamp-ink", "64:retained") : ""}${F.voids ? stamp("VOID-ADJACENT") : ""}</div>
    </header>

    <section class="dp-part">
      <h3><span>Part I</span> Particulars of the visitor</h3>
      <dl class="dp-facts">
        <div><dt>Rooms entered</dt><dd>${new Set(F.rooms).size}</dd></div>
        <div><dt>Plans chosen</dt><dd>${F.plans.length}</dd></div>
        <div><dt>Retreats</dt><dd>${ctx.walk.backtracks}</dd></div>
        <div><dt>Rooms entered twice</dt><dd>${ctx.walk.loops}</dd></div>
        <div><dt>Void passes</dt><dd>${F.voids}</dd></div>
        <div><dt>Items in custody</dt><dd>${F.frags.length}</dd></div>
      </dl>
    </section>

    <section class="dp-part">
      <h3><span>Part II</span> Itinerary</h3>
      ${rows.length > 1 ? `<div class="dp-tw"><table class="dp-itin">
        <thead><tr><th>No.</th><th>Room</th><th>Dated</th><th>Means</th><th>Statement</th></tr></thead>
        <tbody>${rows.map((s, i) => `<tr><td>${omitted + i + 1}</td><td>${s.room}</td><td>${esc(ROOMS[s.room]?.date ?? "")}</td><td>${esc(s.via === "door" ? `Plan ${s.room}` : MEANS[s.via] ?? s.via)}</td><td>${s.say ? `“${esc(s.say)}”` : "—"}</td></tr>`).join("")}</tbody>
      </table></div>${omitted ? `<p class="dp-annex">${omitted} earlier entries are held in the annex.</p>` : ""}` : `<p class="dp-nil">One entry: Room ${F.log[0].room}, ${esc(MEANS[F.log[0].via] ?? "")}. ${stamp("INCOMPLETE", "dp-stamp-sm")}</p>`}
    </section>

    <section class="dp-part">
      <h3><span>Part III</span> Items in custody</h3>
      ${Y.items.length ? `<ol class="dp-items">${Y.items.map(({ f, no, margin, rot }, i) => `<li class="dp-item" style="--r:${rot}deg">
        <p class="dp-it-h"><span class="dp-it-no">Item ${esc(no)}</span><span>${esc(KIND_LABEL[f.kind] ?? f.kind)}</span></p>
        <div class="dp-it-b">${itemBody(f)}</div>
        <p class="dp-it-s">${(f.n ?? 0) >= 3 ? stamp("HABITUAL", "dp-stamp-sm") : ""}${f.from && ctx.damage.voidRooms?.[f.from] ? ` ${stamp("VOID", "dp-stamp-sm")}` : ""}</p>
        ${margin ? `<p class="dp-it-m"${i < 4 ? ` data-frag="line" data-frag-id="64:m${i}"` : ""}>${esc(margin)}</p>` : ""}
      </li>`).join("")}</ol>` : nil}
    </section>

    ${Y.damaged.length || Y.voidRooms.length ? `<section class="dp-part">
      <h3><span>Part IV</span> Condition of the premises</h3>
      ${Y.voidRooms.length ? `<ul class="dp-voids">${Y.voidRooms.map(([n, c]) => `<li><span class="dp-void-n">Room ${n}</span> entered ${c === 1 ? "once" : `${c} times`}. Not repairable. ${stamp("VOID", "dp-stamp-sm")}</li>`).join("")}</ul>` : ""}
      <table class="dp-cond"><tbody>${Y.damaged.map(([n, d]) => `<tr><td>Room ${n}</td><td><span class="dp-bar" style="--v:${clamp(d).toFixed(2)}"></span></td><td>${CONDITION(d)}</td></tr>`).join("")}</tbody></table>
      <p class="dp-annex">Map: ${Math.round((ctx.damage.map || 0) * 100)}% torn. Damage is recorded at its worst and is never revised downward.</p>
    </section>` : ""}

    <section class="dp-part">
      <h3><span>Part ${Y.damaged.length || Y.voidRooms.length ? "V" : "IV"}</span> Received at the counter</h3>
      <div class="dp-counter">
        <div class="dp-env" data-slot="*"></div>
        <div class="dp-env" data-slot="*"></div>
        <div class="dp-env" data-slot="*"></div>
      </div>
    </section>

    <section class="dp-part dp-det">
      <h3><span>Determination</span></h3>
      ${Y.det.map((t, i) => `<p${i === 0 ? ` data-frag="line" data-frag-id="64:det"` : ""}>${esc(t)}${i === Y.det.length - 1 ? '<sup class="fn"><a href="#note-87" aria-label="note 87">87</a></sup>' : ""}</p>`).join("")}
      <p class="dp-sign"><span>Signature of visitor</span><span class="dp-line"></span><span class="dp-unsigned">unsigned</span></p>
    </section>
  </section>`;
  after(anchor, html);

  // Filing happened: the stamp goes with the reader.
  ctx.emit({ kind: "stamp", id: "64:filed", text: `FILED ${Y.caseNo}` });

  // The header stamps come down as they are reached (once each).
  let io = null;
  if (!ctx.reduced && "IntersectionObserver" in window) {
    const stamps = [...article.querySelectorAll(".dp-reg-stamps .dp-stamp")];
    stamps.forEach((s) => s.classList.add("dp-up"));
    io = new IntersectionObserver((es) => {
      for (const e of es) {
        if (!e.isIntersecting) continue;
        e.target.classList.remove("dp-up");
        e.target.classList.add("dp-down");
        io.unobserve(e.target);
      }
    }, { threshold: 0.4, rootMargin: "0px 0px -12% 0px" });
    stamps.forEach((s) => io.observe(s));
  }
  return { leave() { io?.disconnect(); } };
}

const GRAMMARS = {
  33: { name: "deep-graph", make: graph },
  36: { name: "deep-wheel", make: wheel },
  64: { name: "deep-registry", make: registry },
};
